package org.example.ticket.model;

import java.time.Instant;

import org.example.ticket.Ticket;
import org.example.ticket.TicketPriority;
import org.example.ticket.TicketStatus;
import org.example.ticket.TicketType;

/**
 * A ticket as returned by the API. Every field is always present; an optional field that was not
 * set is {@code null}. A deleted ticket is never returned, so there is no {@code deletedAt}.
 *
 * @param id        generated by the database
 * @param createdBy the id of the user who reported the ticket; {@code null} for a ticket created
 *                  before the authors were recorded
 * @param createdAt moment the ticket was created (ISO-8601, UTC, microseconds)
 * @param updatedAt moment of the last change; equal to {@code createdAt} for a new ticket
 */
public record TicketResponse(
        Long id,
        String title,
        String description,
        String stepsToReproduce,
        String expectedResult,
        String actualResult,
        TicketPriority priority,
        TicketStatus status,
        TicketType type,
        Long createdBy,
        Instant createdAt,
        Instant updatedAt) {

    public static TicketResponse of(Ticket ticket) {
        return new TicketResponse(ticket.getId(), ticket.getTitle(), ticket.getDescription(),
                ticket.getStepsToReproduce(), ticket.getExpectedResult(), ticket.getActualResult(),
                ticket.getPriority(), ticket.getStatus(), ticket.getType(), ticket.getCreatedBy(),
                ticket.getCreatedAt(), ticket.getUpdatedAt());
    }
}
